$ErrorActionPreference = 'Stop'
$repoRoot = Split-Path $PSScriptRoot -Parent
$metadata = Get-Content (Join-Path $repoRoot 'config/backend.json') -Raw | ConvertFrom-Json
$directory = Join-Path $repoRoot '.deps/gplall'
$archive = Join-Path $directory 'backend.zip'
$extracted = Join-Path $directory 'release'
New-Item -ItemType Directory -Force $directory | Out-Null
if (-not (Test-Path -LiteralPath $archive)) {
  Invoke-WebRequest -UseBasicParsing -Uri $metadata.url -OutFile $archive
}
if ((Get-FileHash -LiteralPath $archive -Algorithm SHA256).Hash.ToLower() -ne $metadata.sha256) {
  throw 'DXVK-GPLALL archive checksum mismatch; preserve or move the archive before retrying.'
}
# Expand the verified archive each time to avoid reusing modified extracted files.
Expand-Archive -LiteralPath $archive -DestinationPath $extracted -Force
$backend = Join-Path $extracted 'x64/d3d9.dll'
if (-not (Test-Path -LiteralPath $backend)) { throw 'Release has no x64/d3d9.dll' }
Write-Output $backend
